import 'package:accounting_software/app/core/localization/translations/app_key.dart';
import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:accounting_software/app/core/presentation/widgets/crud_editor/crud_editor.dart';
import 'package:accounting_software/app/core/presentation/widgets/app_text_field/app_text_field.dart';
import 'package:accounting_software/app/core/presentation/widgets/app_text/app_text.dart';
import 'package:accounting_software/app/features/catalog/materials/domain/entity/material.dart';
import 'package:accounting_software/app/features/catalog/materials/domain/entity/material_draft.dart';
import 'package:accounting_software/app/features/catalog/materials/presentation/cubit/materials_form/material_form_cubit.dart';
import 'package:accounting_software/app/features/catalog/materials/presentation/localization/materials_keys.dart';
class MaterialEditorDialog extends StatefulWidget{const MaterialEditorDialog({super.key,this.item});final CatalogMaterial? item;@override State<MaterialEditorDialog> createState()=>_MaterialEditorDialogState();}
class _MaterialEditorDialogState extends State<MaterialEditorDialog>{
 late final CrudEditorFields fields;bool active=true;MaterialType? selected;
 TextEditingController get name=>fields['name'];TextEditingController get code=>fields['code'];TextEditingController get description=>fields['description'];
 @override void initState(){super.initState();final e=widget.item;active=e?.isActive??true;selected=e?.materialType;fields=CrudEditorFields(initialValues:{'name':e?.name??'','code':e?.code??'','description':e?.description??''});}
 @override void dispose(){fields.dispose();super.dispose();}
 Future<void> save()=>context.read<MaterialFormCubit>().save(id:widget.item?.id,draft:MaterialDraft(name:name.text.trim(),code:code.text.trim(),description:description.text.trim().isEmpty?null:description.text.trim(),isActive:active,materialType:selected));
 @override Widget build(BuildContext context)=>CrudEditorDialog<MaterialFormCubit,MaterialFormStatus,MaterialFormEffect>(cubit:context.read<MaterialFormCubit>(),fields:fields,mode:widget.item==null?CrudEditorMode.add:CrudEditorMode.edit,labels:const CrudEditorLabels(addTitle:MaterialsKeys.add,editTitle:MaterialsKeys.edit,subtitle:MaterialsKeys.description,duplicateTitle:MaterialsKeys.duplicate,save:MaterialsKeys.save,cancel:MaterialsKeys.cancel),isSaving:(s)=>s==MaterialFormStatus.saving,outcome:(e)=>switch(e){MaterialSavedEffect()=>const CrudEditorSuccess(),MaterialSaveFailedEffect(:final messageKey)=>CrudEditorFailure(messageKey)},onSave:save,builder:(context,scope)=>Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[AppTextField(controller:name,labelKey:MaterialsKeys.name,validator:(v)=>v==null||v.trim().isEmpty?MaterialsKeys.required.tr(context:context):v.trim().length>100?MaterialsKeys.nameTooLong.tr(context:context):null,onChanged:(_)=>scope.clearFailure()),AppTextField(controller:code,labelKey:MaterialsKeys.code,textDirection:TextDirection.ltr,validator:(v)=>v==null||v.trim().isEmpty?MaterialsKeys.required.tr(context:context):v.trim().length>50?MaterialsKeys.codeTooLong.tr(context:context):null,onChanged:(_)=>scope.clearFailure()),DropdownButtonFormField<MaterialType>(value:selected,decoration:InputDecoration(labelText:MaterialsKeys.type.tr(context:context)),items:[for(final v in MaterialType.values)DropdownMenuItem(value:v,child:Text(switch(v){MaterialType.natural=>MaterialsKeys.natural.tr(context:context),MaterialType.synthetic=>MaterialsKeys.synthetic.tr(context:context),MaterialType.blended=>MaterialsKeys.blended.tr(context:context)}))],onChanged:(v){setState(()=>selected=v);scope.changed();}),AppTextField(controller:description,labelKey:MaterialsKeys.description,maxLines:3),SwitchListTile(value:active,title:AppText(active?MaterialsKeys.active:MaterialsKeys.inactive),onChanged:(v){setState(()=>active=v);scope.changed();}),const SizedBox.shrink()]));}
}